create function public.update_transaction(p_id uuid,p_account_id uuid,p_date date,p_description text,p_type public.tx_type,p_amount numeric,p_category text,p_reason text) returns public.transactions language plpgsql security definer set search_path=public as $$declare old_row public.transactions;new_row public.transactions;is_super boolean;begin if auth.uid() is null then raise exception 'Tidak terautentikasi';end if;is_super:=public.has_role(auth.uid(),'super_admin');select * into old_row from public.transactions where id=p_id for update;if not found then raise exception 'Transaksi tidak ditemukan';end if;if not is_super and old_row.ledger is distinct from public.current_ledger() then raise exception 'Tidak memiliki akses ke transaksi ini';end if;if old_row.tx_type in ('transfer_in','transfer_out') or p_type in ('transfer_in','transfer_out') then raise exception 'Transaksi transfer tidak dapat diedit di sini';end if;if is_super and(p_reason is null or char_length(trim(p_reason))<5) then raise exception 'Alasan perubahan wajib diisi (minimal 5 karakter)';end if;if p_amount is null or p_amount<=0 then raise exception 'Nominal harus lebih dari 0';end if;update public.transactions set account_id=p_account_id,tx_date=p_date,description=trim(p_description),tx_type=p_type,amount=round(p_amount,2),category=nullif(trim(coalesce(p_category,'')),'') where id=p_id returning * into new_row;insert into public.audit_logs(transaction_id,ledger,actor_id,action,before_data,after_data,reason,result) values(p_id,old_row.ledger,auth.uid(),'update',to_jsonb(old_row),to_jsonb(new_row),nullif(trim(coalesce(p_reason,'')),''),'success');return new_row;end$$;
create function public.create_transfer(p_from uuid,p_to uuid,p_amount numeric,p_date date,p_note text,p_client_ref uuid) returns uuid language plpgsql security definer set search_path=public as $$declare l public.ledger;lf public.ledger;lt public.ledger;tid uuid:=gen_random_uuid();bal numeric;begin l:=public.current_ledger();if l is null then raise exception 'Hanya Admin 1 / Admin 2 yang dapat transfer';end if;if p_from=p_to then raise exception 'Rekening asal dan tujuan harus berbeda';end if;if p_amount is null or p_amount<=0 then raise exception 'Nominal harus lebih dari 0';end if;perform id from public.bank_accounts where id in(p_from,p_to) order by id for update;select ledger into lf from public.bank_accounts where id=p_from;select ledger into lt from public.bank_accounts where id=p_to;if lf is distinct from l or lt is distinct from l then raise exception 'Rekening tidak valid';end if;if exists(select 1 from public.transactions where client_ref=p_client_ref) then select transfer_id into tid from public.transactions where client_ref=p_client_ref;return tid;end if;select a.opening_balance+coalesce(sum(case when t.tx_type in('income','transfer_in') then t.amount else -t.amount end),0) into bal from public.bank_accounts a left join public.transactions t on t.account_id=a.id where a.id=p_from group by a.id;if bal<p_amount then raise exception 'Saldo rekening asal tidak cukup';end if;insert into public.transactions(ledger,account_id,tx_date,description,tx_type,amount,transfer_id,client_ref,created_by,category) values(l,p_from,p_date,coalesce(nullif(trim(p_note),''),'Transfer internal'),'transfer_out',round(p_amount,2),tid,p_client_ref,auth.uid(),'Transfer'),(l,p_to,p_date,coalesce(nullif(trim(p_note),''),'Transfer internal'),'transfer_in',round(p_amount,2),tid,null,auth.uid(),'Transfer');insert into public.audit_logs(transaction_id,ledger,actor_id,action,after_data,result) values(tid,l,auth.uid(),'transfer',jsonb_build_object('from',p_from,'to',p_to,'amount',p_amount,'date',p_date),'success');return tid;end$$;
create function public.set_opening_balance(p_account_id uuid,p_amount numeric,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare old_row public.bank_accounts;begin if not public.has_role(auth.uid(),'super_admin') then raise exception 'Hanya Super Admin';end if;if p_reason is null or char_length(trim(p_reason))<5 then raise exception 'Alasan wajib diisi';end if;select * into old_row from public.bank_accounts where id=p_account_id for update;if not found then raise exception 'Rekening tidak ditemukan';end if;update public.bank_accounts set opening_balance=round(p_amount,2) where id=p_account_id;insert into public.audit_logs(ledger,actor_id,action,before_data,after_data,reason) values(old_row.ledger,auth.uid(),'opening_balance',jsonb_build_object('account',old_row.name,'opening_balance',old_row.opening_balance),jsonb_build_object('account',old_row.name,'opening_balance',round(p_amount,2)),trim(p_reason));end$$;
create function public.import_transactions(p_file_name text,p_rows jsonb,p_skipped_invalid int) returns public.import_batches language plpgsql security definer set search_path=public as $$declare l public.ledger;b public.import_batches;inserted int;total int;begin l:=public.current_ledger();if l is null then raise exception 'Hanya Admin 1 / Admin 2 yang dapat mengimpor';end if;total:=jsonb_array_length(p_rows);if total=0 then raise exception 'Tidak ada baris valid untuk diimpor';end if;if total>5000 then raise exception 'Maksimal 5000 baris per impor';end if;insert into public.import_batches(ledger,file_name,created_by,status) values(l,left(coalesce(p_file_name,'file.xlsx'),200),auth.uid(),'processing') returning * into b;with src as(select(r->>'account_id')::uuid account_id,(r->>'tx_date')::date tx_date,left(r->>'description',200) description,(r->>'tx_type')::public.tx_type tx_type,round((r->>'amount')::numeric,2) amount,nullif(left(coalesce(r->>'category',''),50),'') category,r->>'fingerprint' fingerprint from jsonb_array_elements(p_rows) r),ins as(insert into public.transactions(ledger,account_id,tx_date,description,tx_type,amount,category,fingerprint,import_id,created_by) select l,account_id,tx_date,description,tx_type,amount,category,fingerprint,b.id,auth.uid() from src where tx_type in('income','expense') on conflict(ledger,fingerprint) where fingerprint is not null do nothing returning 1) select count(*) into inserted from ins;update public.import_batches set rows_total=total+coalesce(p_skipped_invalid,0),rows_imported=inserted,rows_skipped=total-inserted+coalesce(p_skipped_invalid,0),status='completed' where id=b.id returning * into b;insert into public.audit_logs(ledger,actor_id,action,after_data,result) values(l,auth.uid(),'import',jsonb_build_object('batch',b.id,'file',b.file_name,'imported',inserted),'success');return b;end$$;
create function public.set_review_status(p_id uuid,p_status public.review_status) returns void language plpgsql security definer set search_path=public as $$declare old_row public.transactions;begin if not public.has_role(auth.uid(),'super_admin') then raise exception 'Hanya Super Admin yang dapat menandai status';end if;select * into old_row from public.transactions where id=p_id for update;if not found then raise exception 'Transaksi tidak ditemukan';end if;if old_row.review_status=p_status then return;end if;update public.transactions set review_status=p_status,reviewed_by=auth.uid(),reviewed_at=now() where id=p_id;insert into public.audit_logs(transaction_id,ledger,actor_id,action,before_data,after_data,result) values(p_id,old_row.ledger,auth.uid(),'review',jsonb_build_object('review_status',old_row.review_status),jsonb_build_object('review_status',p_status),'success');end$$;
create function public.create_transaction(p_ledger public.ledger,p_account_id uuid,p_date date,p_description text,p_type public.tx_type,p_amount numeric,p_category text,p_client_ref uuid) returns public.transactions language plpgsql security definer set search_path=public as $$declare new_row public.transactions;acc public.bank_accounts;begin if not public.has_role(auth.uid(),'super_admin') then raise exception 'Hanya Super Admin';end if;if p_type not in('income','expense') then raise exception 'Jenis transaksi tidak valid';end if;if p_amount is null or p_amount<=0 then raise exception 'Nominal harus lebih dari 0';end if;if p_description is null or char_length(trim(p_description))=0 then raise exception 'Keterangan wajib diisi';end if;select * into acc from public.bank_accounts where id=p_account_id;if not found then raise exception 'Rekening tidak ditemukan';end if;if acc.ledger is distinct from p_ledger then raise exception 'Rekening tidak sesuai pembukuan';end if;if p_client_ref is not null then select * into new_row from public.transactions where client_ref=p_client_ref;if found then return new_row;end if;end if;insert into public.transactions(ledger,account_id,tx_date,description,tx_type,amount,category,client_ref,created_by) values(p_ledger,p_account_id,p_date,trim(p_description),p_type,round(p_amount,2),nullif(trim(coalesce(p_category,'')),''),p_client_ref,auth.uid()) returning * into new_row;insert into public.audit_logs(transaction_id,ledger,actor_id,action,after_data,result) values(new_row.id,new_row.ledger,auth.uid(),'create',to_jsonb(new_row),'success');return new_row;end$$;
CREATE FUNCTION public.delete_transaction(p_id uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE old_row public.transactions;paired public.transactions;is_super boolean;transfer_key uuid;target_ids uuid[];BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Tidak terautentikasi';END IF;is_super:=public.has_role(auth.uid(),'super_admin');IF p_reason IS NULL OR char_length(trim(p_reason))<5 THEN RAISE EXCEPTION 'Alasan penghapusan wajib diisi (minimal 5 karakter)';END IF;SELECT transfer_id INTO transfer_key FROM public.transactions WHERE id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Transaksi tidak ditemukan';END IF;IF transfer_key IS NOT NULL THEN PERFORM id FROM public.transactions WHERE transfer_id=transfer_key ORDER BY id FOR UPDATE;END IF;SELECT * INTO old_row FROM public.transactions WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Transaksi tidak ditemukan';END IF;IF NOT is_super AND old_row.ledger IS DISTINCT FROM public.current_ledger() THEN RAISE EXCEPTION 'Tidak memiliki akses ke transaksi ini';END IF;IF old_row.tx_type IN('transfer_in','transfer_out') OR old_row.transfer_id IS NOT NULL THEN IF old_row.transfer_id IS NULL OR old_row.transfer_id IS DISTINCT FROM transfer_key THEN RAISE EXCEPTION 'Pasangan transfer tidak valid';END IF;SELECT array_agg(id ORDER BY id) INTO target_ids FROM public.transactions WHERE transfer_id=old_row.transfer_id;IF array_length(target_ids,1) IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'Pasangan transfer tidak lengkap';END IF;SELECT * INTO paired FROM public.transactions WHERE transfer_id=old_row.transfer_id AND id<>old_row.id;IF paired.ledger IS DISTINCT FROM old_row.ledger OR paired.amount IS DISTINCT FROM old_row.amount OR paired.tx_date IS DISTINCT FROM old_row.tx_date OR paired.account_id=old_row.account_id OR NOT((old_row.tx_type='transfer_in' AND paired.tx_type='transfer_out') OR(old_row.tx_type='transfer_out' AND paired.tx_type='transfer_in')) THEN RAISE EXCEPTION 'Pasangan transfer tidak valid';END IF;ELSE target_ids:=ARRAY[old_row.id];END IF;INSERT INTO public.audit_logs(transaction_id,ledger,actor_id,action,before_data,reason,result) SELECT id,ledger,auth.uid(),'delete',to_jsonb(t),trim(p_reason),'success' FROM public.transactions t WHERE id=ANY(target_ids);DELETE FROM public.transactions WHERE id=ANY(target_ids);END$$;
create function public.create_bank_account(p_ledger public.ledger,p_name text,p_opening_balance numeric default 0,p_sort_order int default 0) returns public.bank_accounts language plpgsql security definer set search_path=public as $$declare new_row public.bank_accounts;begin if not public.has_role(auth.uid(),'super_admin') then raise exception 'Hanya Super Admin';end if;if p_name is null or char_length(trim(p_name))=0 then raise exception 'Nama rekening wajib diisi';end if;insert into public.bank_accounts(ledger,name,opening_balance,sort_order) values(p_ledger,trim(p_name),round(coalesce(p_opening_balance,0),2),coalesce(p_sort_order,0)) returning * into new_row;insert into public.audit_logs(ledger,actor_id,action,after_data,result) values(new_row.ledger,auth.uid(),'create_account',jsonb_build_object('account',new_row.name,'opening_balance',new_row.opening_balance,'sort_order',new_row.sort_order),'success');return new_row;end$$;
create function public.update_bank_account(p_id uuid,p_name text,p_sort_order int) returns public.bank_accounts language plpgsql security definer set search_path=public as $$declare old_row public.bank_accounts;new_row public.bank_accounts;begin if not public.has_role(auth.uid(),'super_admin') then raise exception 'Hanya Super Admin';end if;if p_name is null or char_length(trim(p_name))=0 then raise exception 'Nama rekening wajib diisi';end if;select * into old_row from public.bank_accounts where id=p_id for update;if not found then raise exception 'Rekening tidak ditemukan';end if;update public.bank_accounts set name=trim(p_name),sort_order=coalesce(p_sort_order,old_row.sort_order) where id=p_id returning * into new_row;insert into public.audit_logs(ledger,actor_id,action,before_data,after_data,result) values(old_row.ledger,auth.uid(),'update_account',jsonb_build_object('account',old_row.name,'sort_order',old_row.sort_order),jsonb_build_object('account',new_row.name,'sort_order',new_row.sort_order),'success');return new_row;end$$;
create function public.delete_bank_account(p_id uuid) returns void language plpgsql security definer set search_path=public as $$declare old_row public.bank_accounts;begin if not public.has_role(auth.uid(),'super_admin') then raise exception 'Hanya Super Admin';end if;select * into old_row from public.bank_accounts where id=p_id for update;if not found then raise exception 'Rekening tidak ditemukan';end if;if exists(select 1 from public.transactions where account_id=p_id) then raise exception 'Rekening memiliki transaksi dan tidak dapat dihapus';end if;delete from public.bank_accounts where id=p_id;insert into public.audit_logs(ledger,actor_id,action,before_data,result) values(old_row.ledger,auth.uid(),'delete_account',jsonb_build_object('account',old_row.name,'opening_balance',old_row.opening_balance),'success');end$$;
revoke execute on function public.update_transaction,public.create_transfer,public.set_opening_balance,public.import_transactions,public.set_review_status,public.create_transaction,public.delete_transaction,public.create_bank_account,public.update_bank_account,public.delete_bank_account from public,anon;
grant execute on function public.update_transaction,public.create_transfer,public.set_opening_balance,public.import_transactions,public.set_review_status,public.create_transaction,public.delete_transaction,public.create_bank_account,public.update_bank_account,public.delete_bank_account to authenticated,service_role;